head.script:
scwin.screenId = "jldfil15302";

///////// 1. 변수 및 선언 영역 /////////

scwin.sizeX = 440;


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.initValue();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil15302.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil15302.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////



///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_GetLawItemContents_xhr
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_GetLawItemContents_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_GetLawItemContents_xhr", unresolved: "action:self_submit:tx_fn_GetLawItemContents_xhr" };
};

/**
 * @method
 * @name scwin.tx_fn_GetLawDtruleItemContents_xhr
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_GetLawDtruleItemContents_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_GetLawDtruleItemContents_xhr", unresolved: "action:self_submit:tx_fn_GetLawDtruleItemContents_xhr" };
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.winResize
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.winResize = function () {
    /* sdd-asis-lifecycle:begin fn_WinResize — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.resizeX();
    scwin.resizeY();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.resizeX
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.resizeX = function () {
    /* sdd-asis-lifecycle:begin fn_ResizeX — as-is 원문 본문(전환 이관 · 포팅 적용됨) */

    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.resizeY
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.resizeY = function () {
    /* sdd-asis-lifecycle:begin fn_ResizeY — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const sh = document.body.scrollHeight;
    let sizeY = 500;
    if (sh < 500) {
        sizeY = sh + 30;
    }

    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.initValue
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.initValue = async function () {
    /* sdd-asis-lifecycle:begin fn_InitValue — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    await scwin.getLawItemContents();
    await scwin.getLawDtruleItemContents();

    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.getLawItemContents
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.getLawItemContents = async function () {
    /* sdd-asis-lifecycle:begin fn_GetLawItemContents — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.lawItemForm || { elements: [] });
    $c.util.getComponent('dma_GetLawItemContentsXhrReq').set('method', "viewLawItem");
    frm.action = "popLaw.do";
    const result = await scwin.tx_fn_GetLawItemContents_xhr();
    const divObj = $c.util.getComponent("law1");
    divObj.innerHTML = result;
    scwin.sizeX = 440;
    scwin.winResize();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.getLawDtruleItemContents
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.getLawDtruleItemContents = async function () {
    /* sdd-asis-lifecycle:begin fn_GetLawDtruleItemContents — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.lawItemForm || { elements: [] });
    $c.util.getComponent('dma_GetLawItemContentsXhrReq').set('method', "viewLawDtruleItem");
    frm.action = "popLaw.do";
    let result = await scwin.tx_fn_GetLawDtruleItemContents_xhr();
    result = $c.str.trim(result);
    if (result !== '') {
        const divObj = $c.util.getComponent("txt_law2");
        divObj.innerHTML = result;
        scwin.sizeX = 900;
    } else {
        scwin.sizeX = 455;
    }
    scwin.winResize();
    scwin.setTableHeight();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setTableHeight
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.setTableHeight = function () {
    /* sdd-asis-lifecycle:begin fn_SetTableHeight — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const tab1 = $c.util.getComponent("tab1");
    const tab2 = $c.util.getComponent("tab2");
    const height1 = tab1.offsetHeight;
    const height2 = tab2.offsetHeight;
    const maxHeight = (height1 > height2) ? height1 : height2;
    tab1.setStyle('height', maxHeight);
    tab2.setStyle('height', maxHeight);
    /* sdd-asis-lifecycle:end */
};
